def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, max(1.0, DAILY_SALARY * 0.25)))

    prev_bids = []
    danger_bids = []
    soft_bids = []
    urgent_opp = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            prev_bids.append(bid)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                danger_bids.append(bid)
            else:
                soft_bids.append(bid)
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            urgent_opp += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    danger_prev = max(danger_bids) if danger_bids else highest_prev
    soft_prev = max(soft_bids) if soft_bids else avg_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    my_urgent = no_water_days >= 1 or hp <= 4
    critical = no_water_days >= 2 or hp <= 2

    base = DAILY_SALARY * (0.34 + 0.22 * scarcity)

    if day >= 8:
        base += 6.0

    if urgent_opp >= 2:
        base += 5.0
    elif urgent_opp == 0:
        base -= 3.0

    if highest_prev >= 120:
        if my_urgent:
            bid = max(base + 18.0, min(highest_prev * 0.72, DAILY_SALARY * 1.18))
        else:
            bid = min(base - 6.0, DAILY_SALARY * 0.42)
    elif highest_prev >= 85:
        if my_urgent:
            bid = max(base + 12.0, min(danger_prev + 2.5, DAILY_SALARY * 1.08))
        else:
            bid = max(base, soft_prev + 1.5)
    elif highest_prev > 0:
        if scarcity > 0.6 or my_urgent:
            bid = max(base + 8.0, highest_prev + 2.0)
        else:
            bid = max(base, avg_prev + 1.0)
    else:
        bid = base

    if critical:
        bid = max(bid, DAILY_SALARY * 0.98 + 8.0 * scarcity)
    elif my_urgent:
        bid = max(bid, DAILY_SALARY * (0.78 + 0.12 * scarcity))

    reserve_days = 10 - day
    reserve_target = max(0.0, reserve_days * DAILY_SALARY * 0.18)
    spend_cap = budget - reserve_target
    if critical:
        spend_cap = budget
    elif my_urgent:
        spend_cap = max(spend_cap, budget * 0.72)
    else:
        spend_cap = max(spend_cap, budget * 0.45)

    bid = min(bid, spend_cap, budget)
    bid = max(0.0, bid)

    if budget < 25:
        bid = min(bid, budget)
        if my_urgent:
            bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # Collect immediate yesterday traces for alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # Baseline: bid enough to not be starved, but avoid war
    # If supply is higher, water is easier to obtain; bid less.
    if supply >= 22.5:
        base_bid = DAILY_SALARY * 0.45
    elif supply <= 17.5:
        base_bid = DAILY_SALARY * 0.62
    else:
        base_bid = DAILY_SALARY * 0.52

    # React to yesterday behavior: if many opponents ended with 0 budget or very low hp, they likely overbid.
    low_hp_count = 0
    zero_budget_count = 0
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid', None)
        if prev_bid is not None:
            try:
                prev_bids.append(float(prev_bid))
            except Exception:
                pass
        prev_hp_after = prev.get('hp_after', None)
        prev_budget_after = prev.get('budget_after', None)
        if prev_hp_after is not None:
            try:
                if float(prev_hp_after) <= 0.0:
                    low_hp_count += 1
            except Exception:
                pass
        if prev_budget_after is not None:
            try:
                if float(prev_budget_after) <= 0.0:
                    zero_budget_count += 1
            except Exception:
                pass

    # If opponents were punished yesterday (overbidding), we can underbid slightly.
    pressure = 0
    pressure += low_hp_count
    pressure += zero_budget_count

    # If my hp is low or I have gone without water, increase bid to survive.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        urgency = 1
    else:
        urgency = 0

    # If there is evidence of high bids yesterday, avoid matching the maximum; target just above a lower quantile.
    if prev_bids:
        sorted_bids = sorted(prev_bids)
        # Use median-ish target to avoid extremes; ensure index is int.
        median_idx = int(len(sorted_bids) // 2)
        median_bid = float(sorted_bids[median_idx])
        # If there were many high bids, nudge up a bit.
        high_count = sum(1 for b in prev_bids if b >= DAILY_SALARY * 0.8)
        high_ratio = float(high_count) / float(len(prev_bids)) if len(prev_bids) > 0 else 0.0
    else:
        median_bid = base_bid
        high_ratio = 0.0

    # Compute target bid
    target = base_bid

    # If opponents got eliminated/emptied budgets yesterday, reduce bid.
    if pressure >= 2:
        target *= 0.90
    elif pressure == 1:
        target *= 0.97

    # If opponents were bidding aggressively yesterday, increase slightly but not to their max.
    if high_ratio >= 0.34:
        target *= 1.08

    # Urgency override
    if urgency:
        target = max(target, DAILY_SALARY * 0.75)

    # Safety: ensure we don't bid more than budget
    max_affordable = max(0.0, my_budget)

    # Also cap bids based on supply scarcity: fewer water units => slightly higher bids
    # Approximate scarcity factor using supply relative to WATER_REQ.
    # Higher scarcity => higher bid.
    scarcity = 1.0
    if supply > 0:
        scarcity = float(WATER_REQ) / float(supply)
    # scarcity in roughly [0.36..0.6]; map to multiplier range [0.95..1.15]
    if scarcity >= 0.55:
        target *= 1.12
    elif scarcity <= 0.40:
        target *= 0.96

    # Final clamp
    if target > max_affordable:
        bid = max_affordable
    else:
        bid = target

    # Ensure non-negative and at least a minimal bid if possible
    if bid < 0.0:
        bid = 0.0
    # If budget is tiny, still bid it (game likely uses highest bids to allocate water)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    cindy_bid = 0
    if 'Cindy' in opponents_status and opponents_status['Cindy']['alive']:
        prev = opponents_status['Cindy'].get('previous_trace', {})
        cindy_bid = prev.get('bid', 80.0)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if cindy_bid > 0:
        target = cindy_bid * 0.95
        return min(my_status['budget'], max(35.0, target))

    return min(my_status['budget'], 45.0)
